        @JavascriptInterface public void filesystemTool(boolean repair,int partition){runOnUiThread(()->{try{if(app.running)throw new IOException("JOB_BUSY");if(partition<0||partition>128)throw new IOException("FS_PARTITION");UsbDevice device=app.target();String id=app.selected;long epoch=app.deviceEpoch;String details=tr("Drive: ","الوحدة: ")+device.getProductName()+"\n"+device.getDeviceName()+"\n"+tr("Partition number: ","رقم القسم: ")+partition+"\n\n"+tr("Auto-detects FAT12/16/32, exFAT, NTFS, ext2/3/4 or 4 KiB-block F2FS on a supported basic MBR/GPT layout. 0 means a raw filesystem without a partition table. Check is read only. Repair uses fsck.fat/exfat automatic repairs, limited ntfsfix, e2fsck automatic preen or fsck.f2fs and then checks again; it does not mount, defragment or recover deleted files. NTFS repair is not a replacement for Windows chkdsk.","يكتشف FAT12/16/32 أو exFAT أو NTFS أو ext2/3/4 أو F2FS بكتل 4 KiB على تخطيط MBR/GPT بسيط مدعوم. يعني 0 نظام ملفات خاماً دون جدول أقسام. الفحص للقراءة فقط. يستخدم الإصلاح fsck.fat/exfat التلقائي أو ntfsfix المحدود أو e2fsck التلقائي أو fsck.f2fs ثم يعيد الفحص؛ لا يركب الوحدة أو يلغي تجزئتها أو يستعيد المحذوفات. إصلاح NTFS لا يستبدل chkdsk في Windows.");if(repair)details+="\n\n"+tr("EXPERIMENTAL REPAIR WRITES METADATA and may remove damaged entries or truncate files. Automatic mode can refuse severe damage; even failed repair may have changed metadata. Back up files first and fully shut down Windows/other computers that used this drive. Wrong targets, damaged filesystems and interruption can cause data loss. A passing check is not a hardware-health guarantee.","الإصلاح التجريبي يكتب البيانات الوصفية وقد يحذف إدخالات تالفة أو يقصر ملفات. قد يرفض الوضع التلقائي التلف الشديد؛ حتى الإصلاح غير الناجح ربما غير البيانات الوصفية. انسخ الملفات أولاً وأوقف Windows أو الحاسوب الذي استخدم الوحدة إيقافاً كاملاً. قد يسبب الهدف الخاطئ أو تلف النظام أو الانقطاع فقدان بيانات. نجاح الفحص ليس ضماناً لسلامة العتاد.");details+="\n\n"+directUsbNotice();confirm(repair?tr("Review limited filesystem repair","مراجعة إصلاح نظام الملفات المحدود"):tr("Review read-only filesystem check","مراجعة فحص نظام الملفات للقراءة"),details,repair,()->{try{ensureSelected(id);if(epoch!=app.deviceEpoch)throw new IOException("DEVICE_CHANGED");app.queue(repair?"fsRepair":"fsCheck",true,()->{ensureSelected(id);if(epoch!=app.deviceEpoch)throw new IOException("DEVICE_CHANGED");try(UsbDisk disk=new UsbDisk(app.usb(),app.target(),true)){FilesystemTools.Volume volume=FilesystemTools.select(disk,partition,repair);app.formatOptions=volume.kind.toUpperCase(Locale.ROOT)+" / P"+partition+" / LBA"+volume.start;return FilesystemTools.run(app,volume,repair,app::progress,()->app.cancel,name->app.phase=name);}});}catch(Exception e){failure(e);}});}catch(Exception e){failure(e);}});}
        @JavascriptInterface public void partitionMetadata(String mode,int partition,String name){runOnUiThread(()->{try{
            if(app.running)throw new IOException("JOB_BUSY");if((!"gptName".equals(mode)&&!"mbrActive".equals(mode))||partition<1||partition>("mbrActive".equals(mode)?4:128))throw new IOException("PARTITION_LAYOUT");if("gptName".equals(mode))PartitionMetadata.name(name);
            UsbDevice d=app.target();String id=app.selected;long epoch=app.deviceEpoch;
            String details=tr("Selected USB: ","USB المحددة: ")+d.getProductName()+"\n"+d.getDeviceName()+"\nVID:PID "+String.format(Locale.ROOT,"%04X:%04X",d.getVendorId(),d.getProductId())+"\n"+tr("Partition number: ","رقم القسم: ")+partition+"\n\n"+("gptName".equals(mode)?tr("Change GPT partition name to: ","تغيير اسم قسم GPT إلى: ")+name:tr("Mark this MBR primary partition active and clear the active flag on the other primary entries.","تعليم قسم MBR الأولي هذا كنشط ومسح راية النشاط من الإدخالات الأولية الأخرى."))+"\n\n"+tr("WRITES PARTITION METADATA. Back up first. Standard matching GPT copies or basic non-extended MBR only, 512-byte sectors. Does not rename the filesystem, resize, create/delete, mount or install boot code. A GPT name change can break PARTLABEL boot paths. A wrong MBR active flag can prevent BIOS boot. GPT writes backup first then primary; power loss, errors or cancellation after writing may leave inconsistent copies. No automatic rollback. Do not unplug during this short operation.","يكتب بيانات الأقسام الوصفية. انسخ احتياطياً أولاً. يدعم نسختي GPT قياسيتين متطابقتين أو MBR بسيطاً دون أقسام ممتدة وقطاع 512 بايت. لا يغير اسم نظام الملفات ولا الحجم ولا ينشئ أو يحذف أو يركب أو يثبت كود إقلاع. قد يعطل اسم GPT مسارات PARTLABEL، وقد تمنع راية MBR الخاطئة إقلاع BIOS. يكتب GPT الاحتياطية ثم الأساسية؛ قد يترك انقطاع الطاقة أو الخطأ أو الإلغاء بعد الكتابة نسخاً غير متسقة. لا يوجد تراجع تلقائي. لا تفصل الكابل أثناء العملية القصيرة.")+"\n\n"+directUsbNotice();
            confirm(tr("Review partition metadata edit","مراجعة تعديل بيانات الأقسام"),details,true,()->{try{ensureSelected(id);if(epoch!=app.deviceEpoch)throw new IOException("DEVICE_CHANGED");app.queue("partitionEdit",true,()->{ensureSelected(id);if(epoch!=app.deviceEpoch)throw new IOException("DEVICE_CHANGED");try(UsbDisk disk=new UsbDisk(app.usb(),app.target(),true)){PartitionMetadata.Plan plan=PartitionMetadata.plan(disk,mode,partition,name);return PartitionMetadata.apply(disk,plan,app::progress);}});}catch(Exception e){failure(e);}});
        }catch(Exception e){failure(e);}});}
        @JavascriptInterface public void readMap(String mode){runOnUiThread(()->{try{if(app.running)throw new IOException("JOB_BUSY");if(mode.equals("show")){app.readMap(mode,"",0);return;}if(!mode.equals("new")&&!mode.equals("resume"))throw new IOException("READ_MAP_OPTIONS");UsbDevice d=app.target();String id=app.selected;long epoch=app.deviceEpoch;String details=tr("Selected USB: ","USB المحددة: ")+d.getProductName()+"\n"+d.getDeviceName()+"\n\n"+tr("Reads only. A new scan replaces the saved checkpoint only. Resume checks geometry and sampled identity; verify the physical drive yourself. After a failed range the scan stops: reconnect, then Resume continues after that recorded range. Ranges are failed read requests, not proof every sector is bad. Nothing is repaired or remapped.","قراءة فقط. يستبدل الفحص الجديد نقطة الاستكمال المحفوظة فقط. يفحص الاستكمال الهندسة والهوية المأخوذة من عينات؛ تأكد من الوحدة الفعلية بنفسك. يتوقف عند نطاق فاشل؛ أعد التوصيل ثم يستكمل بعد النطاق المسجل. النطاق طلب قراءة فاشل وليس إثباتاً لتلف كل قطاع. لا يُصلح شيء أو تُعاد تعيين قطاعات.")+"\n\n"+directUsbNotice();confirm(tr("Review read-error map","مراجعة خريطة أخطاء القراءة"),details,false,()->{try{app.readMap(mode,id,epoch);}catch(Exception e){failure(e);}});}catch(Exception e){failure(e);}});}
