        @JavascriptInterface public void fsUsb(boolean extract,int partition,double limitGiB){runOnUiThread(()->{try{if(app.running)throw new IOException("JOB_BUSY");if(partition<0||partition>128)throw new IOException("FS_PARTITION");UsbDevice device=app.target();String id=app.selected;long epoch=app.deviceEpoch;String details=tr("Read-only NTFS/ext2/3/4 USB access. No Android filesystem mount or whole-drive temporary copy. Links, reparse points, encrypted and special paths are marked and omitted. A live USB is not an atomic snapshot: stop transfers and safely eject Android's mounted access first. Extraction writes only to a new folder in this device's INTERNAL storage, with file-hash readback; the source USB is never an output. There is no whole-drive source checksum pass for live browsing.","وصول للقراءة فقط إلى USB بنظام NTFS/ext2/3/4 دون تركيب نظام الملفات في أندرويد أو نسخة مؤقتة كاملة. توسم الروابط ونقاط إعادة التحليل والمسارات المشفرة والخاصة ولا تستخرج. USB المباشر ليس لقطة ذرية: أوقف النقل وأخرج الوصول المركب في أندرويد بأمان أولاً. يكتب الاستخراج إلى مجلد جديد في التخزين الداخلي لهذا الجهاز فقط ويتحقق من الملفات بإعادة القراءة؛ USB المصدر ليس وجهة ناتج. لا توجد قراءة بصمة كاملة للوحدة أثناء التصفح المباشر.")+"\n\n"+device.getProductName()+"\n"+device.getDeviceName()+"\n"+tr("Partition: ","القسم: ")+partition+"\n\n"+directUsbNotice();confirm(extract?tr("Review read-only USB file extraction","مراجعة استخراج ملفات USB للقراءة فقط"):tr("Review USB filesystem browsing","مراجعة تصفح نظام ملفات USB"),details,false,()->{try{ensureSelected(id);if(epoch!=app.deviceEpoch)throw new IOException("DEVICE_CHANGED");app.fsUsb(extract,partition,limitGiB,id,epoch);}catch(Exception e){failure(e);}});}catch(Exception e){failure(e);}});}
