        @JavascriptInterface public void authorizeClone(String targetId){runOnUiThread(()->{try{if(app.running)throw new IOException("JOB_BUSY");UsbDevice d=app.usb().getDeviceList().get(targetId);if(d==null)throw new IOException("NO_DEVICE");if(UsbDisk.storageInterface(d)==null)throw new IOException("UNSUPPORTED_USB");if(app.usb().hasPermission(d))return;permissionSelect=false;permissionDevice=targetId;Intent i=new Intent(USB_PERMISSION).setPackage(getPackageName());int flags=PendingIntent.FLAG_UPDATE_CURRENT;if(Build.VERSION.SDK_INT>=31)flags|=PendingIntent.FLAG_MUTABLE;app.usb().requestPermission(d,PendingIntent.getBroadcast(MainActivity.this,0,i,flags));}catch(Exception e){failure(e);}});}
        @JavascriptInterface public void cloneUsb(String targetId){runOnUiThread(()->{try{
            if(app.running)throw new IOException("JOB_BUSY");UsbDevice source=app.target(),target=app.usb().getDeviceList().get(targetId);String sourceId=app.selected;long epoch=app.deviceEpoch;
            if(target==null)throw new IOException("NO_DEVICE");if(sourceId.equals(targetId))throw new IOException("CLONE_SAME");if(!app.usb().hasPermission(target))throw new IOException("USB_PERMISSION");
            String details=tr("READ FROM: ","القراءة من: ")+source.getProductName()+" • "+sourceId+"\n\n"+tr("ERASE AND WRITE TO: ","المحو والكتابة على: ")+target.getProductName()+" • "+targetId+"\n\n"+tr("The destination is fully erased. Both drives must have exactly the same capacity and sector size. After writing, every byte is compared. Cancellation does not undo writes. Use a powered USB hub and back up first.","ستُمحى الوجهة كاملة. يجب تطابق سعة الوحدتين وحجم القطاع تماماً. تُقارن كل البايتات بعد الكتابة. الإلغاء لا يعكس الكتابة. استخدم موزع USB بمصدر طاقة وانسخ بياناتك أولاً.");
            confirm(tr("Clone USB to USB","نسخ USB إلى USB"),details+"\n\n"+directUsbNotice(),true,()->{try{app.queue("clone",true,()->{ensureSelected(sourceId);if(epoch!=app.deviceEpoch)throw new IOException("DEVICE_CHANGED");UsbDevice actual=app.usb().getDeviceList().get(targetId);if(actual==null||actual.getDeviceId()!=target.getDeviceId())throw new IOException("DEVICE_CHANGED");try(UsbDisk src=new UsbDisk(app.usb(),source,true);UsbDisk dst=new UsbDisk(app.usb(),actual,true)){DiskCloner.clone(src,dst,app::progress);}return "CLONE_OK";});}catch(Exception e){failure(e);}});
        }catch(Exception e){failure(e);}});}
        @JavascriptInterface public void addZipFiles(){runOnUiThread(()->{try{if(app.running)throw new IOException("JOB_BUSY");picker(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),CREATEZIP);}catch(Exception e){failure(e);}});}
        @JavascriptInterface public void removeZipInput(int index){runOnUiThread(()->{try{app.removeZipInput(index);}catch(Exception e){failure(e);}});}
        @JavascriptInterface public void createSelectedZip(){runOnUiThread(()->{try{if(app.running)throw new IOException("JOB_BUSY");app.createSelectedZip();}catch(Exception e){failure(e);}});}
        @JavascriptInterface public void splitWim(int sizeMiB){runOnUiThread(()->{try{if(app.running)throw new IOException("JOB_BUSY");app.imageTool("wimSplit",sizeMiB);}catch(Exception e){failure(e);}});}
        @JavascriptInterface public void workshop(String mode,int option){runOnUiThread(()->{try{
            if(app.running)throw new IOException("JOB_BUSY");
            if(mode.equals("split")){app.splitFile(option);return;}
            if(mode.equals("join")||mode.equals("createzip")){if(app.tree.isEmpty())throw new IOException("NO_FOLDER");picker(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),mode.equals("join")?JOIN:CREATEZIP);return;}
            if(mode.equals("sources")){picker(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/zip").putExtra(Intent.EXTRA_TITLE,"USB-Workbench-native-source.zip"),SOURCES);return;}
            if(mode.equals("report")){picker(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("text/plain").putExtra(Intent.EXTRA_TITLE,"USB-Workbench-report-"+System.currentTimeMillis()+".txt"),REPORT);return;}
            if(mode.equals("diagnostic")){app.queue(mode,false,()->app.diagnostic());return;}
            if(mode.equals("imageinfo")){if(app.image.isEmpty())throw new IOException("NO_IMAGE");Uri image=Uri.parse(app.image);long size=app.imageSize;app.queue(mode,false,()->WorkshopTools.inspectImage(app.input(image),size,app::progress));}
        }catch(Exception e){failure(e);}});}
        @JavascriptInterface public void clonePhone(){runOnUiThread(()->{try{app.target();backupDevice=app.selected;backupEpoch=app.deviceEpoch;confirm(tr("Clone USB to phone image","نسخ USB إلى صورة على الهاتف"),tr("Save a NEW .img on internal phone/tablet storage. You need the FULL USB capacity in free space, including unused sectors. USB data is read only. After copying, every byte is compared again. On failure only the new incomplete image is removed. Restore later with Write an image.","احفظ .img جديدة على تخزين الهاتف أو الجهاز اللوحي الداخلي. تحتاج مساحة حرة تساوي سعة USB كاملةً، بما فيها القطاعات غير المستخدمة. يُقرأ USB دون كتابة. بعد النسخ تُقارن كل البايتات مجدداً. عند الفشل تُحذف الصورة الجديدة غير المكتملة فقط. للاستعادة لاحقاً استخدم كتابة صورة نظام.")+"\n\n"+directUsbNotice(),false,()->picker(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/octet-stream").putExtra(Intent.EXTRA_TITLE,"USB-clone-"+System.currentTimeMillis()+".img"),PHONE_CLONE));}catch(Exception e){failure(e);}});}
        @JavascriptInterface public void backup(){runOnUiThread(()->{try{app.target();backupDevice=app.selected;backupEpoch=app.deviceEpoch;confirm(tr("Back up entire drive","نسخ الوحدة كاملةً"),tr("Choose a new .img file on PHONE storage or a different drive. Free space must be at least the full USB capacity, including unused space. An interrupted backup is incomplete.","اختر ملف .img جديداً على الهاتف أو وحدة أخرى. تحتاج مساحة تساوي سعة USB كاملةً، بما فيها المساحة الفارغة. النسخة المتوقفة غير مكتملة.")+"\n\n"+directUsbNotice(),false,()->picker(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/octet-stream").putExtra(Intent.EXTRA_TITLE,"usb-backup-"+System.currentTimeMillis()+".img"),BACKUP));}catch(Exception e){failure(e);}});}
        @JavascriptInterface public void hash(){runOnUiThread(()->{try{if(app.image.isEmpty())throw new IOException("NO_IMAGE");Uri uri=Uri.parse(app.image);long size=app.imageSize;notificationPermission();app.queue("hash",false,()->{try(InputStream in=app.input(uri)){return "SHA-256\n"+DiskTools.sha256(in,size,app::progress);}});}catch(Exception e){failure(e);}});}
        @JavascriptInterface public void zip(){runOnUiThread(()->{try{if(app.image.isEmpty())throw new IOException("NO_IMAGE");Uri uri=Uri.parse(app.image);app.queue("zip",false,()->{StringBuilder out=new StringBuilder("ZIP\n");long inspected=0;byte[] buffer=new byte[16384];try(ZipInputStream in=new ZipInputStream(app.input(uri))){ZipEntry e;int count=0;while((e=in.getNextEntry())!=null){app.progress(count,-1);if(++count>1000)throw new IOException("ZIP_LIMIT");out.append(e.getName()).append(" • ").append(e.getSize()).append(" bytes\n");if(out.length()>100000)throw new IOException("ZIP_LIMIT");int read;while((read=in.read(buffer))!=-1){app.progress(inspected,-1);inspected+=read;if(inspected>268435456L)throw new IOException("ZIP_LIMIT");}in.closeEntry();}if(count==0)throw new IOException("NOT_ZIP");}return out.toString();});}catch(Exception e){failure(e);}});}
        @JavascriptInterface public void extract(){runOnUiThread(()->{
            if(app.running){app.error="JOB_BUSY";return;}if(app.image.isEmpty()){app.error="NO_IMAGE";return;}if(app.tree.isEmpty()){app.error="NO_FOLDER";return;}
            confirm(tr("Extract ZIP","استخراج ZIP"),tr("Extract into a new folder inside your chosen destination. Maximum 10,000 entries and 2 GiB expanded data. Existing files are not overwritten. Password ZIP, RAR, 7z and WIM are unsupported.","استخرج في مجلد جديد داخل الوجهة المختارة. الحد 10000 عنصر و2 GiB من البيانات بعد الاستخراج. لا يتم استبدال الملفات. ZIP المحمي وRAR و7z وWIM غير مدعومة."),false,()->{try{app.extractZip();}catch(Exception e){failure(e);}});
        });}
        @JavascriptInterface public void officialDownload(String id){
            final String page=OfficialDownloads.page(id);if(page==null)return;
            runOnUiThread(()->{
                try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(page)).addCategory(Intent.CATEGORY_BROWSABLE));}
                catch(android.content.ActivityNotFoundException e){new AlertDialog.Builder(MainActivity.this).setMessage(tr("No browser is installed. Open this official address on another device:\n","لا يوجد متصفح مثبت. افتح هذا العنوان الرسمي على جهاز آخر:\n")+page).setPositiveButton(tr("OK","حسناً"),null).show();}
            });
        }
        @JavascriptInterface public void clearHistory(){runOnUiThread(()->confirm(tr("Clear task history","مسح سجل المهام"),tr("Remove this app’s saved task results from this device? Your USB files are unaffected.","هل تريد إزالة نتائج المهام المحفوظة من هذا الجهاز؟ لن تتغير ملفات USB."),false,()->{try{app.clearHistory();}catch(Exception e){failure(e);}}));}
